SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, DATE_TRUNC('YEAR', started_at) AS year_start, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows, SIZE(COLLECT_SET(browser)) AS num_browsers, SIZE(COLLECT_SET(country)) AS num_countries, MIN(started_at) AS started_at FROM sessions GROUP BY DATE_TRUNC('QUARTER', started_at), DATE_TRUNC('YEAR', started_at) ORDER BY sg_rows DESC
